architecture.h4_f:
msg = CBOR{v:1, szöveg, válasz_cím, elküldött_cím}
ct = AES-GCM-256-Titkosítás (k, nonce, msg, aad=szobaazonosító)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, szöveg, válasz_cím?, szálazonosító?, említések?, elküldött_cím}
ct = AES-GCM-256-Titkosítás (szoba_kulcs, nonce, pt, aad=hex(szobaazonosító))
vezeték = CBOR{
  v: 1,
  titkosított szöveg: hex(ct), // változó hosszúságú
  nonce: hex(12B),
  Sender_pseudo: hex(16 B),
  sent_at: unix_ms
}

cryptoWire.h5_f:
külső = CBOR{
  forrás_csomópont: hex32,
  target_user: int64,
  inner_ciphertext: bájtok,
  inner_nonce: bájtok,
  sent_at: unix_ms
}
sig = Ed25519-Sign(forrás_priv, külső)
POST /szövetség/szállítás { boríték: külső, szig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { felhasználónév, jelszó, x25519_public_key, display_name, phone?, email?, avatar_emoji }

201. válasz Létrehozva:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
access_token hasznos terhelés:
  { sub: user_id, jti: device_id, typ: "access", exp: most + 15 perc }
refresh_token hasznos terhelés:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256-aláírva a csomópont 64 bájtos titkával a .env fájlból

auth.h4_f:
register_begin(): kihívás = rand(32)
                    options = { rp.id, user.id, pubKeyCredParams, challenge }
                    visszaküldési lehetőségek

register_finish(attestation):
  a tanúsítvány ellenőrzése a TPM / Secure Enclave root CA
  store { credential_id, public_key, counter: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128 bites hex, ttl: 60 }
QR payload = { nonce, user_id, server: "https://node.example"}

POST /api/authentication/qr/verify { nonce }
  → új eszköz regisztrálva; JWT-k visszatértek.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(szoba_pseudo_salt, feladó_azonosítója)[:16] // 32 hex
titkosított szöveg = AES-GCM-Titkosítás (szoba_kulcs, nonce, CBOR_payload, aad=szoba_azonosító)

Kihúzható keret: { type:"m", szoba, msg:{id, ct, nonce, sender_pseudo, send_at} }

files.h2_f:
init POST /api/files/resumable/init {fájlnév, méret, chunk_size_hint}
            ← {feltöltési_azonosító, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
finalize POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL befejezetlen: 24 óra

files.h4_f:
deny_list = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) in deny_list: return 415

presence.h1_f:
kliens: az első billentyűleütéskor → küldje el {type:"t", állapot:"start"}
         nem küld tovább 3 másodpercig, hacsak az állapot nem változik
         10 másodperccel az utolsó billentyűleütés után → küldje el {type:"t", állapot:"stop"}
vevő: automatikus leállítás 10 másodperccel az utolsó "start" után, ha nem érkezett "stop".

presence.h2_f:
POST /api/rooms/{id}/read { last_read_message_id }

if user.hides_receipts:
   ne tarts ki; ne sugározzon
   ne kézbesítse mások nyugtáit ennek a felhasználónak
más:
   UPSERT read_receipts VALUES (szoba_azonosítója, felhasználói_azonosítója, üzenetazonosítója, NOW())
   adás {type:"r", szoba, felhasználó, üzenet_azonosítója}

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS adás {type:"c", kind:"invite", call_id}
WS adás {type:"c", kind:"ajánlat", sdp}
WS adás {type:"c", kind:"answer", sdp}
WS adás {típus:"c", fajta:"jelölt",jég} × N
POST /api/calls/{call_id}/end

federation.h2_f:
boríték = {
  forrás_csomópont: hex32,
  target_user: int64,
  inner_ciphertext: bájtok,
  inner_nonce: bájtok,
  sent_at : unix_ms,
}
sig = Ed25519Sign(forrás_priv, CBOR(boríték))
POST /szövetség/szállítás { boríték, jel }

gossip.h3_f:
hirdetés = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(hirdetés))
pletyka rakománya: [..., {ad, sig}, ...]

vevő: ellenőrizze a sig-et az ad.pubkey ellen → store iff OK
további: 2^18 kezdő nulla PoW a következőn: {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template with {
  véletlen = a mi véletlenünk,
  szerver_neve = a gazdagépünk neve (vagy ECH-be csomagolva),
  session_id = munkamenetünk azonosítója,
}
JA4 = t13d_xxxx_xxxx_xxxx (egyezik a jelenlegi Chrome-stabil)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {név: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(nyilvános_kulcs_HTTPS_rekordból)
DGA: domain(t) = base32( SHA256(mag ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo)}
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data)}
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
tool = sign_tool
input = forrásfa, keys/release.key
manifeszt = {
  verzió: "0.1.0",
  build_at: unix_ms,
  fájlok: [{elérési út, sha256, méret}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
kimenet = INTEGRITY.sig.json = {manifest, aláírva: pub_hex, sig: sig_hex}

bots.h1_f:
létrehozás: POST /api/bots {felhasználónév, megjelenített_név, kód}
          → {bot_id, token, pubkey}
futás: folyamatban (korutina a csomóponton belül)
      OR külső (long-poll /api/bots/{id}/updates, token-auth'd)
üzenet: {szöveg, aláírás: Ed25519-Sign(bot_priv, canonical_msg)}

